import assert from "node:assert/strict";
import { createHash, generateKeyPairSync, sign } from "node:crypto";
import { readFile } from "node:fs/promises";
import test from "node:test";
import { passkeyAssertionToCircuit } from "credential-proofs-inputs/passkey";


type Fixture = {
  policy: { challenge: string; rpId: string; origin: string; publicKeySec1: string; requireUserVerification: boolean };
  cases: { name: string; accepted: boolean; origin?: string; response: { authenticatorData: string; clientDataJSON: string; signature: string } }[];
};

// Generated by scripts/fixtures/generate-passkey-vectors.py; the Noir
// library runs the same cases (src/browser_vectors.nr).
const fixture = JSON.parse(await readFile(new URL("../../../../fixtures/data/passkey-browser-forms.synthetic.json", import.meta.url), "utf8")) as Fixture;

for (const item of fixture.cases) {
  test(`passkey browser form ${item.name} is ${item.accepted ? "accepted" : "rejected"} as in the circuit`, () => {
    const run = () => passkeyAssertionToCircuit({ response: item.response }, { ...fixture.policy, origin: item.origin ?? fixture.policy.origin });
    if (item.accepted) {
      const witness = run();
      const assertion = witness.assertion as { client_data_json_len: number; signature: number[] };
      assert.equal(assertion.client_data_json_len, Buffer.from(item.response.clientDataJSON, "base64url").length);
      assert.equal(assertion.signature.length, 64);
    } else {
      assert.throws(run);
    }
  });
}

test("passkey importer rejects flags, keys and signatures that the circuit rejects", () => {
  const rpId = "app.example";
  const origin = "https://app.example";
  const challenge = "12345";
  const encoded = Buffer.from(BigInt(challenge).toString(16).padStart(64, "0"), "hex").toString("base64url");
  const clientData = Buffer.from(`{"type":"webauthn.get","challenge":"${encoded}","origin":"${origin}","crossOrigin":false}`);
  const { privateKey, publicKey } = generateKeyPairSync("ec", { namedCurve: "P-256" });
  const other = generateKeyPairSync("ec", { namedCurve: "P-256" });
  const sec1 = (key: typeof publicKey) => {
    const jwk = key.export({ format: "jwk" });
    return `04${Buffer.from(jwk.x!, "base64url").toString("hex")}${Buffer.from(jwk.y!, "base64url").toString("hex")}`;
  };
  const policy = { challenge, rpId, origin, publicKeySec1: sec1(publicKey), requireUserVerification: true };
  const make = (flags: number, signer = privateKey) => {
    const authData = Buffer.concat([createHash("sha256").update(rpId).digest(), Buffer.from([flags, 0, 0, 0, 7])]);
    const der = sign("sha256", Buffer.concat([authData, createHash("sha256").update(clientData).digest()]), signer);
    return { response: { authenticatorData: authData.toString("base64url"), clientDataJSON: clientData.toString("base64url"), signature: der.toString("base64url") } };
  };
  assert.ok(passkeyAssertionToCircuit(make(0x05), policy));
  assert.ok(passkeyAssertionToCircuit(make(0x1d), policy));
  assert.throws(() => passkeyAssertionToCircuit(make(0x07), policy), /reserved flag/);
  assert.throws(() => passkeyAssertionToCircuit(make(0x25), policy), /reserved flag/);
  assert.throws(() => passkeyAssertionToCircuit(make(0x45), policy), /attested credential data or extensions/);
  assert.throws(() => passkeyAssertionToCircuit(make(0x85), policy), /attested credential data or extensions/);
  assert.throws(() => passkeyAssertionToCircuit(make(0x15), policy), /backup state without backup eligibility/);
  assert.throws(() => passkeyAssertionToCircuit(make(0x01), policy), /user-verified/);
  assert.throws(() => passkeyAssertionToCircuit(make(0x05), { ...policy, publicKeySec1: `04${"11".repeat(64)}` }), /valid P-256 point/);
  assert.throws(() => passkeyAssertionToCircuit(make(0x05, other.privateKey), policy), /does not verify/);
  const forged = make(0x05);
  forged.response.signature = Buffer.from("3006020101020101", "hex").toString("base64url");
  assert.throws(() => passkeyAssertionToCircuit(forged, policy), /does not verify/);
});
